//! Typed parsing for the supported SVG filter subset.
use crate::common::{number_list, parse_number, region_number};
use crate::{
    DefinitionSource, attr, matching_end, matching_end_controlled, number, oom, span_bytes,
    unsupported,
};
use vexel_base::{WorkControl, WorkKind};
use vexel_scene::{
    Diagnostic, ErrorKind, Filter, FilterInput, FilterKind, FilterPrimitive, LimitKind, Result,
};
use vexel_xml::{TokenKind, XmlSpan, XmlToken};

pub const FILTER_MAX_COUNT: usize = 4096;
pub const FILTER_MAX_PRIMITIVES: usize = 16;
pub const FILTER_MAX_TOTAL_PRIMITIVES: usize = 65536;
pub const FILTER_MAX_MERGE_INPUTS: usize = 8;

#[derive(Debug, Clone)]
pub struct FilterPlan {
    pub filter: Filter,
    pub primitives: Vec<FilterPrimitive>,
    pub definition: usize,
}
#[derive(Clone, Copy)]
struct ResultName {
    bytes_offset: usize,
    len: usize,
    present: bool,
}

pub fn parse_filter(
    source: &[u8],
    tokens: &[XmlToken],
    value: XmlSpan,
    element: usize,
    control: &mut dyn WorkControl,
) -> Result<FilterPlan> {
    let _view = DefinitionSource::new_controlled(source, tokens, control)?;
    let id = crate::parse_local_url(source, value)?;
    if !valid_id_lookup(source, tokens, id, element, control)?
        || !eq(source, tokens[element].local_name, b"filter")
    {
        return Err(unsupported(value.offset));
    }
    parse_filter_at_controlled(source, tokens, element, control)
}
pub(crate) fn parse_filter_at_controlled(
    source: &[u8],
    tokens: &[XmlToken],
    element: usize,
    control: &mut dyn WorkControl,
) -> Result<FilterPlan> {
    parse_filter_inner(source, tokens, element, Some(control))
}
fn parse_filter_inner(
    source: &[u8],
    tokens: &[XmlToken],
    element: usize,
    mut control: Option<&mut dyn WorkControl>,
) -> Result<FilterPlan> {
    if !tokens
        .get(element)
        .is_some_and(|t| eq(source, t.local_name, b"filter"))
    {
        return Err(unsupported(
            tokens.get(element).map_or(0, |t| t.name.offset),
        ));
    }
    let end = if let Some(control) = control.as_deref_mut() {
        matching_end_controlled(tokens, element, control)?
    } else {
        matching_end(tokens, element)?
    };
    if let Some(control) = control.as_deref_mut() {
        let visits = end
            .checked_sub(element)
            .ok_or_else(|| crate::invalid(tokens[element].name.offset))?;
        control
            .charge(
                WorkKind::TokenVisit,
                u64::try_from(visits).map_err(|_| {
                    crate::limit(LimitKind::Arithmetic, tokens[element].name.offset)
                })?,
            )
            .map_err(|stop| crate::planner_support::stopped(stop))?;
    }
    let mut units = true;
    let mut primitive_units = false;
    if let Some(s) = attr(source, tokens, element, b"filterUnits") {
        units = if eq(source, s, b"userSpaceOnUse") {
            false
        } else if eq(source, s, b"objectBoundingBox") {
            true
        } else {
            return Err(unsupported(s.offset));
        };
    }
    if let Some(s) = attr(source, tokens, element, b"primitiveUnits") {
        primitive_units = if eq(source, s, b"objectBoundingBox") {
            true
        } else if eq(source, s, b"userSpaceOnUse") {
            false
        } else {
            return Err(unsupported(s.offset));
        };
    }
    let mut region = [-0.1, -0.1, 1.2, 1.2];
    let mut custom = false;
    for (i, n) in [b"x".as_slice(), b"y", b"width", b"height"]
        .iter()
        .enumerate()
    {
        if let Some(s) = attr(source, tokens, element, n) {
            custom = true;
            region[i] = region_number(source, s, region[i]).map_err(|_| number(s.offset))?;
            if i >= 2 && region[i] <= 0.0 {
                return Err(number(s.offset));
            }
        }
    }
    let mut primitives = Vec::new();
    primitives
        .try_reserve(8)
        .map_err(|_| oom(tokens[element].name.offset))?;
    let mut names = Vec::<ResultName>::new();
    names
        .try_reserve(8)
        .map_err(|_| oom(tokens[element].name.offset))?;
    let mut i = element + 1;
    while i < end {
        let t = &tokens[i];
        if !is_element(t.kind) || t.depth != tokens[element].depth + 1 {
            i += 1;
            continue;
        }
        if primitives.len() >= FILTER_MAX_PRIMITIVES {
            return Err(crate::limit(LimitKind::Filters, t.name.offset));
        }
        let child_end = if let Some(control) = control.as_deref_mut() {
            matching_end_controlled(tokens, i, control)?
